'use strict';
const STORAGE='kotoba-ch12-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>String(s??'').normalize('NFKC').replace(/[\s。．.、,，？！?!～~…・「」『』\[\]（）()]/g,'').trim();
const gradeWord=(w,b,c)=>{const bOk=clean(b)===clean(w.kana);const cOk=w.c==='X'?/^[xX×]$/.test(String(c).normalize('NFKC').trim()):clean(c)===clean(w.c);return{bOk,cOk,score:(Number(bOk)+Number(cOk))*.5};};
const shuffle=a=>{const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;};
function shuffledTokens(s){let ids=shuffle(s.tokens.map((_,i)=>i));if(ids.map(i=>s.tokens[i]).join('')===s.tokens.join(''))ids.push(ids.shift());return ids;}
const wordBy=id=>WORDS.find(w=>w.id===id);const sentenceBy=id=>SENTENCES.find(s=>s.id===id);const patternBy=id=>PATTERNS.find(p=>p.id===id);
function gradeSentence(s,chosen){const answer=chosen.map(i=>s.tokens[i]).join('');if(chosen.length!==s.tokens.length)return false;if(answer===s.tokens.join(''))return true;if(s.pattern==='p12'){const alternate=[...s.tokens];[alternate[2],alternate[5]]=[alternate[5],alternate[2]];return answer===alternate.join('');}return false;}
let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');}catch{}
const progress=saved.progress||{words:{},sentences:{},matches:{},best:null};progress.words||={};progress.sentences||={};progress.matches||={};
let mock=saved.mock||null;if(mock&&(!mock.a?.every(x=>wordBy(x.id))||!mock.b?.every(x=>sentenceBy(x.id))))mock=null;
const state={view:'home',filter:{ch:'all',group:'all',status:'all',kana:'all'},kanaSelected:null,kanaSection:'basic',kanaReveal:true,pattern:'all',round:null,search:'',modal:false,confirmReset:false};
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({progress,mock}));}catch{toast('Progress could not be saved in this browser. You can still practise.');}}
function record(type,id,ok){const p=progress[type][id]||{wins:0,attempts:0,misses:0};p.attempts++;p.wins=ok?p.wins+1:0;if(!ok)p.misses++;p.last=ok;progress[type][id]=p;save();}
function status(id,type='words'){const p=progress[type][id];return !p?'New':p.wins>=2?'Secure':p.last?'Recalled':'Review';}
function secure(type){return Object.values(progress[type]).filter(p=>p.wins>=2).length;}
function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>t.style.display='none',3500);}
const paths={hiragana:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',home:'<path d="M3 10 12 3l9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',cards:'<rect x="6" y="3" width="14" height="17" rx="2"/><path d="M3 7v13a3 3 0 0 0 3 3m4-13h6m-6 4h4"/>',write:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14z"/><path d="M14 21h7"/>',match:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><path d="m14 17 3 3 5-6"/>',sentences:'<path d="M3 6h18M3 12h12M3 18h8m7-2 3 3-3 3"/>',mock:'<circle cx="12" cy="13" r="8"/><path d="M12 9v5l3 2M9 2h6m-3 0v3"/>',bank:'<path d="M12 5c-4-3-9-1-9-1v16s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1v16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',sound:'<path d="m11 4-5 4H3v8h3l5 4zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',repeat:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 14 6M4 12a8 8 0 0 0 14 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.cards}</svg>`;
const button=(label,action,cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const sourceTag=w=>`Ch. ${w.ch} · PDF p.${w.page} · ${w.group==='core'?'Main vocabulary':w.group==='phrases'?'Expressions':'Related words'}`;
const views=[['home','Overview'],['hiragana','Hiragana groups'],['cards','Recall cards'],['write','Write · Part A'],['match','Kanji match'],['sentences','Rebuild · Part B'],['mock','Mock quiz'],['bank','All words']];
function shell(content){return `<div class="shell"><aside class="sidebar"><button class="brand" data-view="home" aria-label="Kotoba overview"><span class="logo">K</span><span><span class="brand-title">kotoba</span><span class="brand-sub" style="display:block">Your study companion</span></span></button><nav class="nav" aria-label="Study modes">${views.map(([k,label])=>`<button data-view="${k}" class="${state.view===k?'active':''}" ${state.view===k?'aria-current="page"':''}>${icon(k)}${label}</button>`).join('')}</nav><div class="sidebar-foot"><div class="side-note"><span class="dot"></span>Chapters 1–2 only<p class="muted" style="margin-top:9px">Small steps.<br>One word at a time.</p><button class="scope-link" data-action="scope" style="margin-top:18px">Check the syllabus</button></div></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">Japanese I <span style="padding:0 8px">/</span><strong>Chapters 1–2</strong></span><span class="pill"><span class="dot"></span>Made for your quiz</span></header>${content}<footer class="footer-line"><span>PDF pp.1 & 6 · Grammar from Chapters 1–2</span><button class="scope-link" data-action="scope">Scope & quiz rules</button></footer></main></div>${state.modal?scopeModal():''}`;}
function header(title,description,tag=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${tag?`<span class="pill">${tag}</span>`:''}</div>`;}
function scopeModal(){return `<div class="modal-backdrop" data-action="closeBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="scope-title"><div class="row between"><h2 id="scope-title">Your syllabus, kept close.</h2><button data-action="closeScope" aria-label="Close syllabus">${icon('close')}</button></div><p>Vocabulary is transcribed from PDF pages <strong>1 and 6</strong> of your textbook extract (printed pp.28–29 and 38–39). All 90 listed entries are covered; splitting polite and bracketed variants produces <strong>103 recall cards</strong>.</p><h3>Part A · 10 marks</h3><p>Ten Chinese/English prompts. Write <strong>B: Hiragana</strong> and <strong>C: the printed kanji form, or X</strong>. Each column earns 0.5 marks. Both correct = 1 mark. For C, use only the forms supplied in the Japanese vocabulary columns; blank or alphabet-only forms use X.</p><p>The sheet labels B “Hiragana” without a loanword exception. Strict practice therefore uses hiragana readings even for words printed in katakana. Study cards retain the book spelling too. CD, IMC and AKC have no kanji and use X in C.</p><h3>Part B · 10 marks</h3><p>Five reordering questions, 2 marks each. The 50 practice sentences cover all six 練習A patterns in each chapter, the 文型 and their question/answer variants, plus Chapter 1 introduction expressions. They are organised into 16 study groups. No Chapter 3–6 fill-in-the-blank exercises are included.</p><h3>The 15-minute mock</h3><p>Samples 10 main-vocabulary cards and 5 different sentence groups. All expressions and related names are available in the other study modes. The actual quiz questions are unknown. Later-chapter sample vocabulary is excluded from every practice bank.</p><p>Marks are checked by typed spelling and tile order. The real quiz also requires legible handwriting: practise writing on paper alongside the game. “Secure” means two consecutive successful recalls in that mode. Your progress stays in this browser.</p><h3>Input rules</h3><p>Japanese spelling matters: small kana, long vowels and the printed kanji. Harmless spaces, punctuation and placeholder ～ are ignored in Part A. Roman letters do not substitute for hiragana. For X, lowercase x and × are also accepted.</p>${button('Back to practice','closeScope','primary')}</section></div>`;}
function home(){const secured=secure('words'),tried=Object.keys(progress.words).length,patternsDone=PATTERNS.filter(p=>SENTENCES.filter(s=>s.pattern===p.id).every(s=>(progress.sentences[s.id]?.wins||0)>=1)).length;return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A little practice. A lot more confidence.</div><h1>Make every<br>word yours.</h1><p>From your first word to your last sentence.<br>A focused revision game for today’s Chapters 1–2 quiz.</p><div class="row">${button(`Start recalling ${icon('arrow')}`,'goCards','primary')}${button('Practise my mistakes','review','ghost')}</div></div><div class="hero-art" aria-hidden="true"><div class="mini-card"><div class="eyebrow muted">One word at a time</div><div class="jp">学生</div><div class="jp" style="font-size:14px">がくせい</div><div class="small muted" style="margin-top:12px">student · 學生</div></div><div class="stamp">${icon('check')}</div></div></section><section class="stats" aria-label="Learning progress"><div class="stat"><div class="stat-value">${secured}<span class="muted" style="font-size:16px;font-weight:400"> / 103</span></div><div class="stat-label">Words secure · 2 recalls</div></div><div class="stat"><div class="stat-value">${tried}<span class="muted" style="font-size:16px;font-weight:400"> / 103</span></div><div class="stat-label">Words practised</div></div><div class="stat"><div class="stat-value">${patternsDone}<span class="muted" style="font-size:16px;font-weight:400"> / 16</span></div><div class="stat-label">Sentence groups covered</div></div><div class="stat"><div class="stat-value">${progress.best===null?'—':progress.best}<span class="muted" style="font-size:16px;font-weight:400"> / 20</span></div><div class="stat-label">Best mock quiz</div></div></section><div class="section-head"><div><h2>Choose your next small win</h2><p>Recall it. Write it. Put it together.</p></div><span class="small muted">Everything from your supplied pages</span></div><section class="activity-grid"><button class="activity-card" data-view="write"><span class="activity-icon">${icon('write')}</span><span class="tag">Part A · written recall</span><h3>Make it stick</h3><p>See the meaning. Write the hiragana and the required kanji or X.</p><span class="activity-bottom">0.5 marks per answer ${icon('arrow')}</span></button><button class="activity-card" data-view="match"><span class="activity-icon">${icon('match')}</span><span class="tag">Kanji · quick practice</span><h3>Find the match</h3><p>Match each reading to its printed kanji. Remember when the answer is X.</p><span class="activity-bottom">Only syllabus forms ${icon('arrow')}</span></button><button class="activity-card" data-view="sentences"><span class="activity-icon">${icon('sentences')}</span><span class="tag">Part B · sentence order</span><h3>Piece it together</h3><p>Tap the word tiles into place. Practise every pattern, one sentence at a time.</p><span class="activity-bottom">50 sentences · 16 groups ${icon('arrow')}</span></button></section><section class="mock-banner"><div><div class="eyebrow" style="color:#c5d3bb;margin-bottom:6px">Ready for a dress rehearsal?</div><h3>${mock&&!mock.done?'Your mock quiz is in progress.':'15 minutes. 20 marks. You’ve got this.'}</h3><p>10 vocabulary questions + 5 sentence puzzles. Same format as your information sheet.</p></div><button class="button" data-view="mock">${mock&&!mock.done?'Resume mock quiz':'Try the mock quiz'} ${icon('arrow')}</button></section><section class="kana-home-banner"><div><span class="eyebrow muted">A NEW WAY TO FIND YOUR WORDS</span><h3>Start with a hiragana.</h3><p class="small muted">Tap a character, browse its words, then practise just that group.</p></div><button class="button" data-view="hiragana"><span class="jp">あ · か · さ</span> Explore groups ${icon('arrow')}</button></section><p class="scope-note">103 cards include polite and optional forms, expressions and related words from PDF pp.1 & 6. Learning aids are separate from the timed mock. <button class="scope-link" data-action="scope">See exactly what’s included.</button></p>`;}
function options(values,selected){return values.map(([v,t])=>`<option value="${v}" ${selected===v?'selected':''}>${t}</option>`).join('');}
function filters(sentence=false,hideKana=false){return `<div class="filters"><select class="filter" data-filter="ch" aria-label="Chapter">${options([['all','Both chapters'],['1','Chapter 1 · p.1'],['2','Chapter 2 · p.6']],state.filter.ch)}</select>${sentence?`<select class="filter" data-pattern aria-label="Sentence pattern">${options([['all','All 16 sentence groups'],...PATTERNS.map(p=>[p.id,`Ch.${p.ch} · ${p.title}`])],state.pattern)}</select>`:`<select class="filter" data-filter="group" aria-label="Vocabulary section">${options([['all','All page sections'],['core','Main vocabulary'],['phrases','Expressions & variants'],['related','Countries & related names']],state.filter.group)}</select>`}<select class="filter" data-filter="status" aria-label="Practice selection">${options([['all','All items'],['review','Needs practice'],['new','Not tried yet']],state.filter.status)}</select>${!sentence&&!hideKana?`<select class="filter" data-filter="kana" aria-label="First hiragana">${options([['all','Any first hiragana'],...HIRAGANA_KEYS.filter(([k])=>WORDS.some(w=>hiraganaInitial(w)===k)).map(([k,r])=>[k,`${k} · ${r}`])],state.filter.kana||'all')}</select>`:''}</div>`;}
function pool(mode,ignoreKana=false){const sentence=mode==='sentences';return(sentence?SENTENCES:WORDS).filter(x=>{if(state.filter.ch!=='all'&&x.ch!==Number(state.filter.ch))return false;if(sentence&&state.pattern!=='all'&&x.pattern!==state.pattern)return false;if(!sentence&&state.filter.group!=='all'&&x.group!==state.filter.group)return false;if(!sentence&&!ignoreKana&&state.filter.kana&&state.filter.kana!=='all'&&hiraganaInitial(x)!==state.filter.kana)return false;const p=progress[sentence?'sentences':mode==='match'?'matches':'words'][x.id];if(state.filter.status==='review')return !p||p.wins<2;if(state.filter.status==='new')return !p;return true;});}
function begin(mode,ids){const items=ids||shuffle(pool(mode).map(x=>x.id));state.round={mode,ids:items,index:0,correct:0,missed:[],revealed:false,checked:false,assisted:false,result:null,order:null,chosen:[],options:null,selected:null,b:'',c:'',hint:false};prepareQuestion();}
function prepareQuestion(){const r=state.round;if(!r||r.index>=r.ids.length)return;r.revealed=false;r.checked=false;r.assisted=false;r.result=null;r.chosen=[];r.options=null;r.selected=null;r.b='';r.c='';r.hint=false;if(r.mode==='sentences')r.order=shuffledTokens(sentenceBy(r.ids[r.index]));if(r.mode==='match'){const w=wordBy(r.ids[r.index]);let other=shuffle([...new Set(WORDS.filter(x=>x.c!==w.c&&x.c!=='X').map(x=>x.c))]);r.options=shuffle(w.c==='X'?['X',...other.slice(0,3)]:[w.c,'X',...other.slice(0,2)]);}}
function current(){return state.round?.ids[state.round.index];}
function roundBar(){const r=state.round;return `<div class="round-info"><span>ROUND ${r.index+1} / ${r.ids.length}</span><span>${r.correct} correct so far</span></div><div class="progress-bar"><div class="progress-fill" style="width:${100*r.index/r.ids.length}%"></div></div>`;}
function completeRound(ok){const r=state.round;if(ok)r.correct++;else if(!r.missed.includes(current()))r.missed.push(current());r.checked=true;}
function nextQuestion(){state.round.index++;prepareQuestion();render();}
function roundEnd(){const r=state.round;return `<div class="study-wrap paper result-center"><div class="eyebrow muted">Round complete</div><h2 style="margin:15px 0">${r.missed.length?'Good practice. Let’s keep it going.':'A lovely clean sweep.'}</h2><div class="result-score" style="margin:24px 0">${r.correct}<small> / ${r.ids.length}</small></div><p class="muted">${r.missed.length?`${r.missed.length} items are ready for another look.`:'Another successful recall will help these words stick.'}</p><div class="card-actions">${r.missed.length?button('Practise missed items','repeatMissed','coral'):''}${button('Start a new round','restart','primary')}</div></div>`;}
function noItems(){return `<div class="empty paper"><h2>Nothing in this selection.</h2><p class="muted">Try another chapter or reset the filters.</p><div class="card-actions">${button('Show all items','resetFilters','primary')}</div></div>`;}
function practice(mode){if(!state.round||state.round.mode!==mode)begin(mode);const r=state.round;const meta={cards:['Recall, then reveal.','Say or write the answer before you turn the card. Be honest with yourself — that is how it sticks.','103 cards'],write:['Make it stick.','Chinese / English → B: Hiragana + C: printed kanji or X. Each answer is worth 0.5 marks.','Part A · 10 marks'],match:['Find the match.','Match the reading to the written form taught on your pages. X means no kanji form is supplied.','Practice mode'],sentences:['Piece it together.','Tap every tile in order, including punctuation. Tap a placed tile to return it to the bank.','Part B · 10 marks']}[mode];let html=header(...meta)+filters(mode==='sentences');if(mode!=='sentences'&&state.filter.kana&&state.filter.kana!=='all')html+=`<div class="kana-practice-note"><span>Practising words beginning with <strong class="jp">${esc(state.filter.kana)}</strong></span><button class="scope-link" data-action="backKana">Back to this group</button></div>`;if(!r.ids.length)return html+noItems();if(r.index>=r.ids.length)return html+roundEnd();html+=`<section class="study-wrap">${roundBar()}${mode==='cards'?flashcard():mode==='write'?writeCard():mode==='match'?matchCard():sentenceCard()}</section>`;if(mode==='sentences')html+=patternReference();return html;}
function flashcard(){const w=wordBy(current()),r=state.round;return `<div class="flashcard"><div class="eyebrow">${sourceTag(w)}</div>${!r.revealed?`<div class="question">${esc(w.zh)}</div><div class="english">${esc(w.en)}</div><p class="small muted" style="margin-top:35px">Can you recall the hiragana and kanji / X?</p>`:`<div class="small muted">${esc(w.zh)} · ${esc(w.en)}</div><div class="answer jp" lang="ja">${esc(w.kana)}</div><div class="small muted" style="margin-bottom:8px">C · KANJI / X</div><div class="answer-c ${w.c==='X'?'no-kanji':''} jp" lang="ja">${w.c==='X'?'X · no kanji':esc(w.c)}</div>${w.jp!==w.kana?`<div class="small muted" style="margin-top:18px">Book spelling: <span class="jp" lang="ja">${esc(w.jp)}</span></div>`:''}${w.note?`<div class="footnote">${esc(w.note)}</div>`:''}${!w.jp.includes("～")?`<button class="button ghost" data-action="speak" style="margin-top:20px" aria-label="Listen to the Japanese word">${icon('sound')} Listen</button>`:""}`}</div><div class="card-actions">${!r.revealed?button('Reveal answer','flip','primary'):button(`${icon('repeat')} Again`,'again','ghost')+button(`Got it ${icon('check')}`,'got','primary')}</div><p class="shortcut">${!r.revealed?'Space to reveal':'← Again · → Got it'} · “Secure” needs two successful recalls</p>`;}
function writeCard(){const w=wordBy(current()),r=state.round;return `<div class="paper"><div class="eyebrow muted">${sourceTag(w)}</div><div class="write-prompt" style="margin-top:20px">${esc(w.zh)}</div><p class="muted">${esc(w.en)}</p>${w.note&&['1-c2','1-c6','1-06'].includes(w.id)?`<p class="small muted" style="margin-top:12px">${esc(w.note)}</p>`:''}<div class="answer-grid"><div><label class="field-label" for="answer-b">B · HIRAGANA <span class="muted">0.5 mark</span></label><input id="answer-b" class="input jp ${r.checked?(r.result.bOk?'correct':'wrong'):''}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(r.b)}" ${r.checked?'disabled':''} placeholder="Type hiragana" data-answer="b">${r.checked?`<div class="answer-result ${r.result.bOk?'correct-text':'wrong-text'}">${r.result.bOk?'✓ 0.5 mark':'0 marks · Correct:'} <span class="jp">${esc(w.kana)}</span></div>`:''}</div><div><label class="field-label" for="answer-c">C · KANJI / X <span class="muted">0.5 mark</span></label><input id="answer-c" class="input jp ${r.checked?(r.result.cOk?'correct':'wrong'):''}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(r.c)}" ${r.checked?'disabled':''} placeholder="Printed form, or X" data-answer="c">${r.checked?`<div class="answer-result ${r.result.cOk?'correct-text':'wrong-text'}">${r.result.cOk?'✓ 0.5 mark':'0 marks · Correct:'} <span class="jp">${esc(w.c)}</span></div>`:''}</div></div>${r.checked?`<div class="feedback ${r.result.score===1?'':'bad'}"><strong>${r.result.score} / 1 mark</strong><p>${r.result.score===1?'Both columns are correct.':r.result.score===.5?'One column is correct. The sheet awards half a mark.':'Read the two answers, then try this word again at the end of the round.'}</p>${w.jp!==w.kana?`<p>Book spelling: <span class="jp">${esc(w.jp)}</span>. B follows the sheet’s hiragana instruction.</p>`:''}${w.note?`<p>${esc(w.note)}</p>`:''}</div>`:''}<div class="card-actions">${r.checked?button('Next word '+icon('arrow'),'next','primary'):button('Check both answers','checkWrite','primary')}</div><p class="small muted" style="text-align:center;margin-top:15px">Use your Japanese keyboard. Enter checks both answers.</p></div>`;}
function matchCard(){const w=wordBy(current()),r=state.round;return `<div class="paper" style="text-align:center"><div class="eyebrow muted">${sourceTag(w)}</div><div class="match-prompt jp" lang="ja">${esc(w.jp)}</div><p class="muted">${esc(w.zh)} · ${esc(w.en)}</p><div class="options">${r.options.map((c,i)=>`<button class="option jp ${r.checked&&c===w.c?'correct':r.checked&&c===r.selected?'wrong':''}" data-match="${i}" ${r.checked?'disabled':''}><span class="number">${i+1}</span>${esc(c)}</button>`).join('')}</div>${r.checked?`<div class="feedback ${r.selected===w.c?'':'bad'}"><strong>${r.selected===w.c?'Matched!':'The correct match is '+esc(w.c)+'.'}</strong><p>${w.c==='X'?'No kanji form is supplied for this entry. Use X in column C.':`Remember this pairing: ${esc(w.kana)} → ${esc(w.c)}.`}</p>${w.note?`<p>${esc(w.note)}</p>`:''}</div><div class="card-actions">${button('Next match '+icon('arrow'),'next','primary')}</div>`:''}</div><p class="shortcut">Keys 1–4 to choose · Enter for the next match</p>`;}
function tiles(s,order,chosen,locked=false,mockIndex=null){const attrs=mockIndex===null?'':`data-mock-index="${mockIndex}"`;return `<div class="token-area ${chosen.length?'filled':''}" aria-label="Your sentence">${chosen.length?chosen.map((id,i)=>`<button class="tile jp" lang="ja" data-return="${i}" ${attrs} ${locked?'disabled':''} aria-label="Return ${esc(s.tokens[id])} to word bank">${esc(s.tokens[id])}</button>`).join(''):'<span class="empty-hint">Your sentence goes here. Tap a tile below.</span>'}</div><div class="token-bank" aria-label="Shuffled word bank">${order.map(id=>`<button class="tile jp" lang="ja" data-tile="${id}" ${attrs} ${locked||chosen.includes(id)?'disabled':''}>${esc(s.tokens[id])}</button>`).join('')}</div>`;}
function sentenceCard(){const r=state.round,s=sentenceBy(current()),p=patternBy(s.pattern);return `<div class="paper"><div class="row between"><span class="eyebrow muted">CHAPTER ${s.ch} · SENTENCE REBUILD</span><span class="chip">${status(s.id,'sentences')}</span></div><div class="sentence-prompt">${esc(s.prompt)}</div>${tiles(s,r.order,r.chosen,r.checked)}${r.hint?`<div class="hint"><strong>${esc(p.title)}</strong><div class="jp">${esc(p.formula)}</div><p>${esc(p.tip)}</p></div>`:''}${r.checked?`<div class="feedback ${r.result?'':'bad'}"><strong>${r.result?(r.assisted?'Correct with help — try it unaided next time.':'That’s the right order. +2 / 2'):r.revealed?'Study the order, then try again later.':'Not quite — look at this order.'}</strong><div class="jp" lang="ja">${esc(s.tokens.join(''))}</div><p>${esc(p.tip)}</p><p class="small">${esc(p.source)}${s.note?' · '+esc(s.note):''}</p></div>`:''}<div class="card-actions">${r.checked?button('Next sentence '+icon('arrow'),'next','primary'):button('Clear','clearTiles','ghost')+button('Pattern hint','hint','ghost')+button('Check order','checkSentence','primary',r.chosen.length!==s.tokens.length?'disabled':'')}</div>${!r.checked?`<div style="text-align:center;margin-top:14px"><button class="scope-link" data-action="revealSentence">Show answer & mark for review</button></div>`:''}</div>`;}
function patternReference(){return `<details class="details"><summary>All 16 study groups · grammar reference</summary><p>All six 練習A patterns in each chapter, grouped with the question and answer variants taught on the supplied pages. The labels below are revision aids.</p><div class="pattern-list">${PATTERNS.map(p=>`<button class="pattern-card" data-start-pattern="${p.id}"><div class="eyebrow muted">CH.${p.ch} · ${SENTENCES.filter(s=>s.pattern===p.id).length} PUZZLES</div><h3 style="margin-top:8px">${esc(p.title)}</h3><div class="jp">${esc(p.formula)}</div><p>${esc(p.tip)}</p><p style="margin-top:8px;font-size:10px">${esc(p.source)}</p></button>`).join('')}</div></details>`;}
function bankRows(){const term=state.search.toLowerCase();const words=pool('cards').filter(w=>[w.zh,w.en,w.jp,w.kana,w.c].some(s=>s.toLowerCase().includes(term)));return `<div class="small muted" style="margin:15px 0">${words.length} forms · a polite or bracketed alternative gets its own card</div><div class="table-wrap"><table class="word-table"><thead><tr><th>A · Meaning</th><th>B · Hiragana</th><th>C · Kanji / X</th><th>Recall progress</th></tr></thead><tbody>${words.map(w=>`<tr><td><strong>${esc(w.zh)}</strong><div class="muted">${esc(w.en)}</div><div class="muted" style="margin-top:6px">Ch.${w.ch} · PDF p.${w.page}</div></td><td><span class="jp" lang="ja">${esc(w.kana)}</span>${w.jp!==w.kana?`<div class="muted">Book: <span class="jp" style="font-size:13px">${esc(w.jp)}</span></div>`:''}</td><td><span class="jp" lang="ja">${esc(w.c)}</span>${w.note?`<div class="muted" style="max-width:250px;margin-top:6px">${esc(w.note)}</div>`:''}</td><td><span class="status-badge ${status(w.id)==='Secure'?'learned':''}">${status(w.id)}</span></td></tr>`).join('')||'<tr><td colspan="4">No words match this search.</td></tr>'}</tbody></table></div>`;}
function bank(){return header('Every word, in one place.','The complete page-by-page reference. Kanji forms match the supplied Japanese columns; do not substitute other kanji.','103 forms')+filters()+`<div class="bank-top"><input class="input search" type="search" aria-label="Search words" data-search placeholder="Search a meaning, reading or kanji…" value="${esc(state.search)}">${button('Recall this selection','goCards','primary')}</div><div id="bank-rows">${bankRows()}</div>`;}
function mockIntro(){return header('Your quiz rehearsal.','A fresh set of questions, with the exact timing and marks from your information sheet.','15 minutes')+`<section class="study-wrap paper"><div class="eyebrow muted">CHAPTERS 1–2 · 20 MARKS</div><h2 style="margin:18px 0 10px">Take a breath. You know the format.</h2><p class="muted" style="font-size:13px">Work through both parts. You can revisit your answers until you submit or the timer reaches zero.</p><div class="result-breakdown"><div class="score-card"><strong>10 questions</strong><div class="small">Part A · 10 marks</div><p class="small muted" style="margin-top:10px">Write hiragana + kanji / X.<br>0.5 marks for each column.</p></div><div class="score-card"><strong>5 questions</strong><div class="small">Part B · 10 marks</div><p class="small muted" style="margin-top:10px">Reorder the word tiles.<br>2 marks per correct sentence.</p></div></div><div class="info-box" style="margin-top:22px">Samples the 62 main-vocabulary forms and five different sentence groups. No hints or corrections until submission. Expressions and related names are covered in the other modes.</div><p class="small muted">For handwriting practice, write your answers on paper too. The sheet gives no marks for illegible handwriting.</p><div class="card-actions">${button('Start 15-minute mock '+icon('arrow'),'startMock','coral')}</div></section>`;}
function startMock(){const a=shuffle([1,2].flatMap(ch=>shuffle(WORDS.filter(w=>w.group==='core'&&w.ch===ch)).slice(0,5))).map(w=>({id:w.id,b:'',c:''}));const groups=shuffle([...shuffle(PATTERNS.filter(p=>p.ch===1)).slice(0,2),...shuffle(PATTERNS.filter(p=>p.ch===2)).slice(0,3)]);const b=groups.map(p=>{const s=shuffle(SENTENCES.filter(x=>x.pattern===p.id))[0];return{id:s.id,order:shuffledTokens(s),chosen:[]};});mock={a,b,deadline:Date.now()+15*60*1000,started:Date.now(),done:false,tab:'a',confirm:false};save();render();}
function timeLeft(){return Math.max(0,Math.ceil((mock.deadline-Date.now())/1000));}
function formatTime(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function mockQuiz(){if(!mock)return mockIntro();if(mock.done)return mockResult();const aDone=mock.a.filter(x=>x.b.trim()&&x.c.trim()).length,bDone=mock.b.filter(x=>x.chosen.length===sentenceBy(x.id).tokens.length).length;return header('One question at a time.','Your answers are saved as you go. The timer continues if you leave or reload this page.')+`<div class="mock-top"><div class="mock-tabs"><button data-mock-tab="a" class="${mock.tab==='a'?'active':''}">Part A · ${aDone}/10</button><button data-mock-tab="b" class="${mock.tab==='b'?'active':''}">Part B · ${bDone}/5</button></div><div style="text-align:right"><div class="timer ${timeLeft()<60?'warn':''}" role="timer" aria-label="Time remaining">${formatTime(timeLeft())}</div><div class="small muted">TIME REMAINING</div></div></div><div class="study-wrap">${mock.tab==='a'?`<p class="small muted">B: hiragana. C: printed kanji / X. 0.5 marks for each column.</p>${mock.a.map((q,i)=>{const w=wordBy(q.id);return `<section class="mock-question"><div class="mock-q-title">${i+1}. ${esc(w.zh)}</div><div class="small muted">${esc(w.en)}</div><div class="answer-grid"><div><label class="field-label" for="mock-b-${i}">B · HIRAGANA</label><input class="input jp" id="mock-b-${i}" data-mock-field="b" data-mock-index="${i}" value="${esc(q.b)}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false"></div><div><label class="field-label" for="mock-c-${i}">C · KANJI / X</label><input class="input jp" id="mock-c-${i}" data-mock-field="c" data-mock-index="${i}" value="${esc(q.c)}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false"></div></div></section>`;}).join('')}<div class="card-actions"><button class="button primary" data-mock-tab="b">Go to Part B ${icon('arrow')}</button></div>`:`<p class="small muted">Put every tile in order. 2 marks per correct sentence. Tap a placed tile to undo it.</p>${mock.b.map((q,i)=>{const s=sentenceBy(q.id);return `<section class="mock-question"><div class="eyebrow muted">QUESTION ${i+1} · 2 MARKS</div><div class="sentence-prompt">${esc(s.prompt)}</div>${tiles(s,q.order,q.chosen,false,i)}</section>`;}).join('')}`}<div style="margin-top:35px;border-top:1px solid var(--line);padding-top:22px">${mock.confirm?`<div class="info-box">You have ${10-aDone} unfinished vocabulary questions and ${5-bDone} unfinished sentences. Submit now for your score, or keep working.</div><div class="card-actions">${button('Keep working','cancelSubmit','ghost')}${button('Submit quiz now','finishMock','coral')}</div>`:`<div class="card-actions">${button('Submit both parts','confirmSubmit','coral')}</div>`}</div></div>`;}
function finishMock(timedout=false){if(!mock||mock.done)return;mock.done=true;mock.timedout=timedout;mock.finished=Date.now();mock.aResults=mock.a.map(q=>{const result=gradeWord(wordBy(q.id),q.b,q.c);record('words',q.id,result.score===1);return result;});mock.bResults=mock.b.map(q=>{const ok=gradeSentence(sentenceBy(q.id),q.chosen);record('sentences',q.id,ok);return ok;});mock.aScore=mock.aResults.reduce((n,r)=>n+r.score,0);mock.bScore=mock.bResults.filter(Boolean).length*2;mock.score=mock.aScore+mock.bScore;progress.best=Math.max(progress.best||0,mock.score);save();state.view='mock';render();window.scrollTo({top:0,behavior:'smooth'});}
function mockResult(){return header('Your practice paid off.','Review the details below, then give the missed items another go.','Mock complete')+`<div class="study-wrap"><div class="paper result-center"><div class="eyebrow muted">${mock.timedout?'TIME IS UP · ANSWERS SUBMITTED':'CHAPTERS 1–2 · YOUR RESULT'}</div><div class="result-score" style="margin:25px 0">${mock.score}<small> / 20</small></div><p class="muted">${mock.score>=18?'You’re finding your rhythm. Keep the spelling precise.':mock.score>=12?'A solid foundation. A little focused revision will help.':'Now you know exactly what to practise next.'}</p><div class="result-breakdown"><div class="score-card"><strong>${mock.aScore} / 10</strong><span class="small">Part A · vocabulary</span></div><div class="score-card"><strong>${mock.bScore} / 10</strong><span class="small">Part B · sentence order</span></div></div><div class="card-actions">${button('Review missed words','mockMissedWords','ghost')}${button('Review missed sentences','mockMissedSentences','ghost')}${button('New mock quiz','newMock','primary')}</div></div><details class="details" open><summary>Part A · every answer</summary>${mock.a.map((q,i)=>{const w=wordBy(q.id),r=mock.aResults[i];return `<div class="result-row"><div class="row between"><strong>${i+1}. ${esc(w.zh)} · ${esc(w.en)}</strong><span class="${r.score===1?'correct-text':'wrong-text'}">${r.score} / 1</span></div><div class="small muted" style="margin-top:10px">YOUR B <span class="jp ${r.bOk?'correct-text':'wrong-text'}">${esc(q.b)||'—'}</span> · YOUR C <span class="jp ${r.cOk?'correct-text':'wrong-text'}">${esc(q.c)||'—'}</span></div><div class="jp">B: ${esc(w.kana)} · C: ${esc(w.c)}</div></div>`;}).join('')}</details><details class="details" open><summary>Part B · every sentence</summary>${mock.b.map((q,i)=>{const s=sentenceBy(q.id),ok=mock.bResults[i];return `<div class="result-row"><div class="row between"><strong>${i+1}. ${esc(s.prompt)}</strong><span class="${ok?'correct-text':'wrong-text'}">${ok?'2':'0'} / 2</span></div><div class="small muted" style="margin-top:10px">YOUR ORDER</div><div class="jp ${ok?'correct-text':'wrong-text'}">${esc(q.chosen.map(x=>s.tokens[x]).join(''))||'—'}</div><div class="small muted" style="margin-top:10px">CORRECT ORDER</div><div class="jp">${esc(s.tokens.join(''))}</div><p>${esc(patternBy(s.pattern).tip)}</p></div>`;}).join('')}</details></div>`;}
function render(){const page=state.view==='home'?home():state.view==='bank'?bank():state.view==='hiragana'?hiraganaView():state.view==='mock'?mockQuiz():practice(state.view);$('#app').innerHTML=shell(page);if(state.modal)setTimeout(()=>$('.modal button')?.focus(),0);}
function navigate(view){state.view=view;state.modal=false;state.round=null;render();window.scrollTo({top:0,behavior:'smooth'});}
function resetFilters(){state.filter={ch:'all',group:'all',status:'all',kana:'all'};state.pattern='all';state.round=null;}
function speak(wordId=current()){if(!('speechSynthesis' in window)){toast('Speech is unavailable on this device. Use the printed reading.');return;}const w=wordBy(wordId);if(!w)return;const voices=speechSynthesis.getVoices();const japanese=voices.find(v=>/^ja/i.test(v.lang));if(!japanese){toast('No Japanese voice is installed on this device. The reading is shown on the card.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(w.jp.replace(/[～~]/g,''));utterance.lang='ja-JP';utterance.voice=japanese;utterance.rate=.8;utterance.onerror=()=>toast('Audio could not play. The reading is shown on the card.');speechSynthesis.speak(utterance);}
function run(action){const r=state.round;switch(action){case'kanaGrid':state.kanaSelected=null;state.filter.kana='all';state.view='hiragana';state.round=null;render();window.scrollTo({top:0,behavior:'smooth'});break;case'toggleKanaAnswers':state.kanaReveal=!state.kanaReveal;render();break;case'backKana':chooseHiragana(state.filter.kana);break;case'goCards':navigate('cards');break;case'review':resetFilters();state.filter.status='review';navigate('write');break;case'scope':state.modal=true;render();break;case'closeScope':state.modal=false;render();break;case'closeBackdrop':break;case'flip':r.revealed=true;render();break;case'got':case'again':{const ok=action==='got';record('words',current(),ok);completeRound(ok);nextQuestion();break;}case'checkWrite':if(!r.checked){r.result=gradeWord(wordBy(current()),r.b,r.c);record('words',current(),r.result.score===1);completeRound(r.result.score===1);render();}break;case'next':nextQuestion();break;case'restart':begin(state.view);render();break;case'repeatMissed':begin(state.view,shuffle(r.missed));render();break;case'resetFilters':resetFilters();render();break;case'clearTiles':r.chosen=[];render();break;case'hint':r.hint=true;r.assisted=true;render();break;case'checkSentence':if(!r.checked){r.result=gradeSentence(sentenceBy(current()),r.chosen);record('sentences',current(),r.result&&!r.assisted);completeRound(r.result&&!r.assisted);render();}break;case'revealSentence':if(!r.checked){r.revealed=true;r.result=false;r.assisted=true;record('sentences',current(),false);completeRound(false);render();}break;case'speak':speak();break;case'startMock':startMock();break;case'newMock':mock=null;save();render();break;case'confirmSubmit':mock.confirm=true;render();break;case'cancelSubmit':mock.confirm=false;render();break;case'finishMock':finishMock();break;case'mockMissedWords':{const ids=mock.a.filter((q,i)=>mock.aResults[i].score<1).map(q=>q.id);if(!ids.length){toast('All vocabulary answers were correct.');break;}resetFilters();state.view='write';begin('write',ids);render();window.scrollTo({top:0,behavior:'smooth'});break;}case'mockMissedSentences':{const ids=mock.b.filter((q,i)=>!mock.bResults[i]).map(q=>q.id);if(!ids.length){toast('All sentence orders were correct.');break;}resetFilters();state.view='sentences';begin('sentences',ids);render();window.scrollTo({top:0,behavior:'smooth'});break;}}}
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-action]');if(!target||target.disabled)return;if(target.dataset.kana){chooseHiragana(target.dataset.kana);return;}if(target.dataset.kanaSection){state.kanaSection=target.dataset.kanaSection;render();return;}if(target.dataset.kanaDrill){startHiraganaDrill(target.dataset.kanaDrill);return;}if(target.dataset.kanaListen){speak(target.dataset.kanaListen);return;}if(target.dataset.view){navigate(target.dataset.view);return;}if(target.dataset.action){if(target.dataset.action==='closeBackdrop'){if(e.target===target){state.modal=false;render();}return;}run(target.dataset.action);return;}if(target.dataset.match!==undefined){const r=state.round;if(r.checked)return;r.selected=r.options[Number(target.dataset.match)];const ok=r.selected===wordBy(current()).c;record('matches',current(),ok);completeRound(ok);render();return;}if(target.dataset.tile!==undefined||target.dataset.return!==undefined){const isMock=target.dataset.mockIndex!==undefined;const q=isMock?mock.b[Number(target.dataset.mockIndex)]:state.round;if((isMock&&mock.done)||(!isMock&&q.checked))return;if(target.dataset.tile!==undefined){const id=Number(target.dataset.tile);if(!q.chosen.includes(id))q.chosen.push(id);}else q.chosen.splice(Number(target.dataset.return),1);if(isMock){save();const y=window.scrollY;render();window.scrollTo(0,y);}else render();return;}if(target.dataset.startPattern){state.pattern=target.dataset.startPattern;state.filter.ch='all';state.filter.status='all';state.view='sentences';begin('sentences');render();window.scrollTo({top:0,behavior:'smooth'});return;}if(target.dataset.mockTab){mock.tab=target.dataset.mockTab;save();render();window.scrollTo({top:0,behavior:'smooth'});}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.answer)state.round[t.dataset.answer]=t.value;if(t.dataset.mockField){mock.a[Number(t.dataset.mockIndex)][t.dataset.mockField]=t.value;save();const count=mock.a.filter(q=>q.b.trim()&&q.c.trim()).length;const tab=$('[data-mock-tab="a"]');if(tab)tab.textContent=`Part A · ${count}/10`;}if(t.hasAttribute('data-search')){state.search=t.value;$('#bank-rows').innerHTML=bankRows();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.filter){state.filter[t.dataset.filter]=t.value;state.round=null;render();}if(t.hasAttribute('data-pattern')){state.pattern=t.value;state.filter.ch='all';state.round=null;render();}});
document.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Escape'&&state.modal){run('closeScope');return;}if(state.modal&&e.key==='Tab'){const focusable=[...document.querySelectorAll('.modal button')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(state.modal)return;const isInput=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(isInput){if(e.key==='Enter'&&state.view==='write'&&!state.round.checked){e.preventDefault();run('checkWrite');}return;}const r=state.round;if(!r||r.index>=r.ids.length)return;if(state.view==='cards'){if(e.code==='Space'&&!r.revealed){e.preventDefault();run('flip');}else if(r.revealed&&e.key==='ArrowLeft'){e.preventDefault();run('again');}else if(r.revealed&&e.key==='ArrowRight'){e.preventDefault();run('got');}}if(state.view==='match'&&!r.checked&&/^[1-4]$/.test(e.key))$(`[data-match="${Number(e.key)-1}"]`)?.click();if(e.key==='Enter'&&r.checked&&!['BUTTON','A'].includes(e.target.tagName)){e.preventDefault();run('next');}});
setInterval(()=>{if(mock&&!mock.done){const time=timeLeft(),el=$('.timer');if(el){el.textContent=formatTime(time);el.classList.toggle('warn',time<60);}if(time===0)finishMock(true);}},1000);
if('speechSynthesis' in window)speechSynthesis.getVoices();
render();
